styles.appendedRules:
/* The local container controls the calendar header independently of viewport width. */
.iui-root .iui-care-provider{container-type:inline-size}
@container(max-width:575px){.iui-root .iui-care-calendar{grid-template-columns:repeat(2,minmax(0,1fr))}.iui-root .iui-care-month{grid-column:1/-1}.iui-root .iui-care-calendar>[data-care-action=previous-month],.iui-root .iui-care-calendar>[data-care-action=next-month]{min-inline-size:0;max-inline-size:100%}}
